window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-5cb39d99e429853a"]={"versions": [{"id": "FIG-5cb39d99e429853a", "releases": ["R4.1.3", "R4.2.2", "R4.3.1", "R18-10_R4.4.0_R1.5.0", "R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Zeitablaufdiagramm (Timing Diagram) zur Veranschaulichung des Mechanismus der Buslastreduzierung (Bus Load Reduction) im CAN-Netzwerkmanagement (<code>CanNm</code>) der AUTOSAR Classic Platform. Das Diagramm stellt das koordinierte Sendeverhalten mehrerer Netzwerkknoten auf einem gemeinsamen CAN-Bus über eine kontinuierliche Zeitachse (<code>time [ms]</code>) dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Drei Netzwerkknoten als parallele Zeitstränge:</p>\n<ul class=\"fig-list\"><li><code>Node 1</code>: Netzwerkknoten mit Sendestopp-Ereignis (<code>Stop Transmission Node 1</code>).\n</li><li><code>Node 2</code>: Netzwerkknoten mit nachfolgendem Sendestopp-Ereignis (<code>Stop Transmission Node 2</code>).\n</li><li><code>Node 3</code>: Verbleibender aktiver Netzwerkknoten.\n</li></ul>\n<p class=\"fig-p\">Signal- und Zeitparameter:</p>\n<ul class=\"fig-list\"><li><code>Transmission of a NM Message</code>: Fetter vertikaler Balken zur Kennzeichnung des Sendezeitpunkts einer NM-PDU.\n</li><li>Gestrichelte vertikale Hilfslinien: Kennzeichnung von Empfangs- bzw. Synchronisationszeitpunkten über Knotengrenzen hinweg.\n</li><li>Konfigurationsparameter:\n<ul class=\"fig-list\"><li><code>CANNM_MSG_CYCLE_TIME</code>: Standard-Sendezykluszeit (70 ms).\n</li><li><code>CANNM_MSG_REDUCED_TIME</code>: Knotenspezifische reduzierte Zykluszeiten (Node 1: 40 ms, Node 2: 50 ms, Node 3: 60 ms).\n</li></ul>\n</li><li>Lokale Timer-Werte je Knoten (<code>Timer</code>), die dynamisch zwischen reduzierter Zeit und zyklischer Zeit angepasst werden.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Initialphase / Mehrknotenbetrieb:\n<ul class=\"fig-list\"><li>Alle drei Knoten nehmen am NM-Cluster teil.\n</li><li>Durch den Empfang einer fremden NM-Botschaft (gestrichelte Linie) wird der lokale Sendetimer des empfangenden Knotens auf seinen spezifischen Wert <code>CANNM_MSG_REDUCED_TIME</code> zurückgesetzt bzw. neu geladen.\n</li><li>Sendet kein anderer Knoten zuvor, läuft der Timer bis zu <code>CANNM_MSG_CYCLE_TIME</code> (70 ms) ab, woraufhin der jeweilige Knoten selbst sendet.\n</li><li>Node 1 sendet nach Ablauf von 40 ms (ausgelöst durch den vorherigen NM-Empfang) und startet seinen Zyklus mit 70 ms.\n</li></ul>\n</li><li>Sendestopp Node 1 (<code>Stop Transmission Node 1</code>):\n<ul class=\"fig-list\"><li>Node 1 stellt das Senden eigener NM-Botschaften ein.\n</li><li>Node 2 übernimmt das Senden nach Ablauf seiner reduzierten Zeitspanne von 50 ms nach dem letzten relevanten Empfang.\n</li></ul>\n</li><li>Sendestopp Node 2 (<code>Stop Transmission Node 2</code>):\n<ul class=\"fig-list\"><li>Node 2 stellt ebenfalls die Übertragung ein.\n</li></ul>\n</li><li>Einzelknotenbetrieb (Node 3):\n<ul class=\"fig-list\"><li>Node 3 empfängt keine weiteren NM-Botschaften mehr. Nach Ablauf der reduzierten Phase von 60 ms sendet Node 3. Da keine externen Botschaften mehr eintreffen, sendet Node 3 fortan periodisch im vollen Zyklus <code>CANNM_MSG_CYCLE_TIME</code> von 70 ms.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm verdeutlicht die Funktionsweise des optionalen AUTOSAR-Features zur Buslastreduzierung (<code>CanNmBusLoadReductionEnabled</code>).</p>\n<ul class=\"fig-list\"><li>Durch gestaffelte Konfiguration der Werte für <code>CANNM_MSG_REDUCED_TIME</code> (<code>Node 1 &lt; Node 2 &lt; Node 3 &lt; CANNM_MSG_CYCLE_TIME</code>) wird priorisiert festgelegt, welcher Knoten bei mehreren sendebereiten Stationen als erster eine Botschaft überträgt.\n</li><li>Der Empfang einer NM-Botschaft unterdrückt bzw. verzögert die Aussendung anderer Knoten und reduziert so das Gesamtaufkommen an Netzwerkmanagement-Botschaften auf dem Bus.\n</li><li>Für Entwickler und Systemkonfiguratoren ist darauf zu achten, dass <code>CANNM_MSG_REDUCED_TIME</code> stets kleiner als <code>CANNM_MSG_CYCLE_TIME</code> gewählt wird, um ein deterministisches Zurücksetzen der Timer und eine geordnete Übernahme bei Ausfall oder Sendestopp einzelner Knoten zu gewährleisten.\n</li></ul>"}, {"id": "FIG-3b315064d042b1da", "releases": ["R21-11", "R22-11", "EXTERN"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Zeitablaufdiagramm (Timing Diagram) zur Veranschaulichung des Mechanismus der Buslastreduzierung (Bus Load Reduction) im CAN-Netzwerkmanagement (<code>CanNm</code>) der AUTOSAR Classic Platform. Das Diagramm stellt das koordinierte Sendeverhalten mehrerer Netzwerkknoten auf einem gemeinsamen CAN-Bus über eine kontinuierliche Zeitachse (<code>time [ms]</code>) dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Drei Netzwerkknoten als parallele Zeitstränge:</p>\n<ul class=\"fig-list\"><li><code>Node 1</code>: Netzwerkknoten mit Sendestopp-Ereignis (<code>Stop Transmission Node 1</code>).\n</li><li><code>Node 2</code>: Netzwerkknoten mit nachfolgendem Sendestopp-Ereignis (<code>Stop Transmission Node 2</code>).\n</li><li><code>Node 3</code>: Verbleibender aktiver Netzwerkknoten.\n</li></ul>\n<p class=\"fig-p\">Signal- und Zeitparameter:</p>\n<ul class=\"fig-list\"><li><code>Transmission of a NM Message</code>: Fetter vertikaler Balken zur Kennzeichnung des Sendezeitpunkts einer NM-PDU.\n</li><li>Gestrichelte vertikale Hilfslinien: Kennzeichnung von Empfangs- bzw. Synchronisationszeitpunkten über Knotengrenzen hinweg.\n</li><li>Konfigurationsparameter:\n<ul class=\"fig-list\"><li><code>CANNM_MSG_CYCLE_TIME</code>: Standard-Sendezykluszeit (70 ms).\n</li><li><code>CANNM_MSG_REDUCED_TIME</code>: Knotenspezifische reduzierte Zykluszeiten (Node 1: 40 ms, Node 2: 50 ms, Node 3: 60 ms).\n</li></ul>\n</li><li>Lokale Timer-Werte je Knoten (<code>Timer</code>), die dynamisch zwischen reduzierter Zeit und zyklischer Zeit angepasst werden.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Initialphase / Mehrknotenbetrieb:\n<ul class=\"fig-list\"><li>Alle drei Knoten nehmen am NM-Cluster teil.\n</li><li>Durch den Empfang einer fremden NM-Botschaft (gestrichelte Linie) wird der lokale Sendetimer des empfangenden Knotens auf seinen spezifischen Wert <code>CANNM_MSG_REDUCED_TIME</code> zurückgesetzt bzw. neu geladen.\n</li><li>Sendet kein anderer Knoten zuvor, läuft der Timer bis zu <code>CANNM_MSG_CYCLE_TIME</code> (70 ms) ab, woraufhin der jeweilige Knoten selbst sendet.\n</li><li>Node 1 sendet nach Ablauf von 40 ms (ausgelöst durch den vorherigen NM-Empfang) und startet seinen Zyklus mit 70 ms.\n</li></ul>\n</li><li>Sendestopp Node 1 (<code>Stop Transmission Node 1</code>):\n<ul class=\"fig-list\"><li>Node 1 stellt das Senden eigener NM-Botschaften ein.\n</li><li>Node 2 übernimmt das Senden nach Ablauf seiner reduzierten Zeitspanne von 50 ms nach dem letzten relevanten Empfang.\n</li></ul>\n</li><li>Sendestopp Node 2 (<code>Stop Transmission Node 2</code>):\n<ul class=\"fig-list\"><li>Node 2 stellt ebenfalls die Übertragung ein.\n</li></ul>\n</li><li>Einzelknotenbetrieb (Node 3):\n<ul class=\"fig-list\"><li>Node 3 empfängt keine weiteren NM-Botschaften mehr. Nach Ablauf der reduzierten Phase von 60 ms sendet Node 3. Da keine externen Botschaften mehr eintreffen, sendet Node 3 fortan periodisch im vollen Zyklus <code>CANNM_MSG_CYCLE_TIME</code> von 70 ms.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm verdeutlicht die Funktionsweise des optionalen AUTOSAR-Features zur Buslastreduzierung (<code>CanNmBusLoadReductionEnabled</code>).</p>\n<ul class=\"fig-list\"><li>Durch gestaffelte Konfiguration der Werte für <code>CANNM_MSG_REDUCED_TIME</code> (<code>Node 1 &lt; Node 2 &lt; Node 3 &lt; CANNM_MSG_CYCLE_TIME</code>) wird priorisiert festgelegt, welcher Knoten bei mehreren sendebereiten Stationen als erster eine Botschaft überträgt.\n</li><li>Der Empfang einer NM-Botschaft unterdrückt bzw. verzögert die Aussendung anderer Knoten und reduziert so das Gesamtaufkommen an Netzwerkmanagement-Botschaften auf dem Bus.\n</li><li>Für Entwickler und Systemkonfiguratoren ist darauf zu achten, dass <code>CANNM_MSG_REDUCED_TIME</code> stets kleiner als <code>CANNM_MSG_CYCLE_TIME</code> gewählt wird, um ein deterministisches Zurücksetzen der Timer und eine geordnete Übernahme bei Ausfall oder Sendestopp einzelner Knoten zu gewährleisten.\n</li></ul>"}], "trans": [{"from": "FIG-5cb39d99e429853a", "to": "FIG-3b315064d042b1da", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
